(function(root){
const VERSION=1, KEY='netstudy-atmmt-v1';
function fresh(){return {version:VERSION,completed:[],marked:[],history:[],active:null,seen:[]}}
function validate(s){if(!s||s.version!==1||!Array.isArray(s.completed)||!Array.isArray(s.marked)||!Array.isArray(s.history)||!Array.isArray(s.seen))throw Error('Bản sao lưu không đúng định dạng NetStudy.');for(const h of s.history){if(!Array.isArray(h.ids)||!h.answers||!Number.isFinite(h.started)||!Number.isFinite(h.ended))throw Error('Lịch sử không hợp lệ.')}if(s.active&&(!Array.isArray(s.active.ids)||!s.active.ids.length||!s.active.answers||!Array.isArray(s.active.flags)||!Number.isFinite(s.active.started)||!Number.isInteger(s.active.index)||s.active.index<0||s.active.index>=s.active.ids.length||!['learn','test','exam'].includes(s.active.mode)||(s.active.mode==='exam'&&(!Number.isFinite(s.active.deadline)||s.active.ids.length!==40))))throw Error('Bài đang làm không hợp lệ.');for(const session of [...s.history,...(s.active?[s.active]:[])]){if(!session.ids.length||!session.answers||Array.isArray(session.answers)||typeof session.answers!=='object')throw Error('Dữ liệu câu trả lời không hợp lệ.');if(typeof session.id!=='string'||!/^\d+$/.test(session.id)||typeof session.title!=='string'||!['learn','test','exam'].includes(session.mode))throw Error('Thông tin lượt làm bài không hợp lệ.');if(new Set(session.ids).size!==session.ids.length)throw Error('Bản sao lưu có câu hỏi trùng.');for(const [id,v] of Object.entries(session.answers)){if(!session.ids.includes(id)||!Number.isInteger(v)||v<0||v>3)throw Error('Câu trả lời trong sao lưu không hợp lệ.')}}return s}
function shuffle(a,rng=Math.random){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function seeded(seed){return ()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
const matrix={'1':4,'2a':3,'2b':3,'3':6,'4':5,'5':5,'6':6,'7':5,'8':3};
const levelMatrix={'1':[1,2,1],'2a':[1,1,1],'2b':[1,2,0],'3':[2,3,1],'4':[1,3,1],'5':[2,2,1],'6':[2,3,1],'7':[1,3,1],'8':[1,1,1]};
function makeExam(bank,fixed=false,seen=[]){const rng=fixed?seeded(533):Math.random;let chosen=[];for(const [chapter,n] of Object.entries(matrix)){let pool=bank.filter(q=>q.chapter===chapter);if(pool.length<n)throw Error('Ngân hàng chưa đủ câu cho Bài '+chapter);pool=shuffle(pool,rng);if(!fixed)pool.sort((a,b)=>Number(seen.includes(a.id))-Number(seen.includes(b.id)));let selected=[];const [recognize,understand,apply]=levelMatrix[chapter];const targets={'Nhận biết':recognize,'Thông hiểu':understand,'Vận dụng':apply};for(const [level,count]of Object.entries(targets)){const available=pool.filter(q=>q.level===level);selected.push(...available.slice(0,count))}for(const q of pool){if(selected.length>=n)break;if(!selected.includes(q))selected.push(q)}chosen.push(...selected.slice(0,n))}return shuffle(chosen,rng).map(q=>q.id)}
function grade(session,bank,now=Date.now()){let correct=0,wrong=0,blank=0,topics={};const map=new Map(bank.map(q=>[q.id,q]));for(const id of session.ids){const q=map.get(id);if(!q)continue;const a=session.answers[id];let good=a===q.correct;if(a===undefined||a===null)blank++;else if(good)correct++;else wrong++;const key=q.chapter+' · '+q.topic;topics[key]??={correct:0,total:0,chapter:q.chapter};topics[key].total++;if(good)topics[key].correct++}const elapsed=Math.max(0,Math.min(now,session.deadline||now)-session.started);return{correct,wrong,blank,total:session.ids.length,score:correct/session.ids.length*10,rate:correct/session.ids.length*100,elapsed,topics}}
root.StudyCore={KEY,fresh,validate,shuffle,seeded,matrix,levelMatrix,makeExam,grade};if(typeof module!=='undefined')module.exports=root.StudyCore;
})(typeof window!=='undefined'?window:globalThis);
